using System.Net;
using System.Net.Http.Json;
using System.Text.Json.Nodes;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Mvc.Testing;
using Microsoft.AspNetCore.Identity;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.DependencyInjection.Extensions;
using Microsoft.Extensions.Configuration;
using MyProjectManagement;
public sealed class SecurityFactory:WebApplicationFactory<Program>{public readonly MemoryAccounts Accounts=new();protected override void ConfigureWebHost(IWebHostBuilder b){b.UseEnvironment("SecurityTests").UseContentRoot(Environment.GetEnvironmentVariable("MPM_TEST_SOURCE")!);b.ConfigureServices(s=>{s.RemoveAll<IAccountStore>();s.AddSingleton<IAccountStore>(Accounts);});}}
public sealed class MemoryAccounts:IAccountStore{
 public readonly Guid WorkspaceId=Guid.NewGuid();public AppUser? Account;public string? Upgraded;public int Attempts;public bool RoleActive=true;
 public void Seed(string password,bool mustChange=false,bool oldHash=false){var u=new AppUser(Guid.NewGuid(),WorkspaceId,"test@example.test","",true,null,false,mustChange,0,null,Guid.NewGuid().ToString());var h=new PasswordHasher<AppUser>(Microsoft.Extensions.Options.Options.Create(new PasswordHasherOptions{IterationCount=oldHash?10000:600000}));Account=u with{Hash=h.HashPassword(u,password)};}
 public Task<AppUser?> Find(string key,bool email=false)=>Task.FromResult(Account is not null&&(email?string.Equals(Account.Email,key,StringComparison.OrdinalIgnoreCase):Account.Id.ToString()==key)?Account:null);
 public Task<Snapshot> Workspace(AppUser u){var snapshot=new Snapshot{Id=WorkspaceId,Owner=RoleActive?u.Id:Guid.NewGuid(),Settings=new JsonObject()};return Task.FromResult(snapshot);}
 public Task Failed(AppUser u){Attempts++;if(Account is not null)Account=Account with{Failures=Attempts,LockedUntil=Attempts>=5?DateTime.UtcNow.AddMinutes(15):null};return Task.CompletedTask;}
 public Task<AppUser?> SignedIn(AppUser u,string? hash){Upgraded=hash;if(Account is null||u.Stamp!=Account.Stamp||Account.Disabled)return Task.FromResult<AppUser?>(null);Account=Account with{Hash=hash??Account.Hash,Failures=0,LockedUntil=null};return Task.FromResult(Account);}
 public Task<AppUser?> Password(AppUser u,string hash){if(Account is null||u.Stamp!=Account.Stamp)return Task.FromResult<AppUser?>(null);Account=Account with{Hash=hash,MustChange=false,Stamp=Guid.NewGuid().ToString()};return Task.FromResult(Account);}
 public Task Revoke(AppUser u){if(Account?.Stamp==u.Stamp)Account=Account with{Stamp=Guid.NewGuid().ToString()};return Task.CompletedTask;}
}
public static class SecurityTestRunner{
 const string Pass="A long unique test passphrase 48!";
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
 static async Task<string> Csrf(HttpClient c){var j=await c.GetFromJsonAsync<JsonObject>("/api/session");return j!["csrf"]!.GetValue<string>();}
 static async Task<HttpResponseMessage> Post(HttpClient c,string path,object body,bool csrf=true){using var request=new HttpRequestMessage(HttpMethod.Post,path){Content=JsonContent.Create(body)};if(csrf)request.Headers.Add("X-CSRF-Token",await Csrf(c));return await c.SendAsync(request);}
 static HttpClient Client(SecurityFactory f)=>f.CreateClient(new WebApplicationFactoryClientOptions{BaseAddress=new Uri("https://app.example.test"),AllowAutoRedirect=false,HandleCookies=true});
 public static async Task Main(){
 Environment.SetEnvironmentVariable("ConnectionStrings__Default","Server=unused-for-isolated-security-tests");Environment.SetEnvironmentVariable("DataProtection__KeyPath",Path.Combine(Path.GetTempPath(),"mpm-security-tests-"+Guid.NewGuid()));
 var src=Environment.GetEnvironmentVariable("MPM_TEST_SOURCE")??Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,"../../../../../source"));Environment.SetEnvironmentVariable("MPM_TEST_SOURCE",src);
 var config=new ConfigurationBuilder().Build();foreach(var bad in new[]{"short password","password123456789","aaaaaaaaaaaaaaaaaaaa"}){bool denied=false;try{PasswordPolicy.Validate(bad,config);}catch(ApiError){denied=true;}Check(denied,"Password policy must reject weak value");}PasswordPolicy.Validate(Pass,config);PasswordPolicy.Validate("correct horse battery staple",config);
 using(var factory=new SecurityFactory()){factory.Accounts.Seed("legacy-pass-12!",oldHash:true);using var c=Client(factory);
 var root=await c.GetAsync("/");Check(root.StatusCode==HttpStatusCode.OK,"Application HTML loads");var html=await root.Content.ReadAsStringAsync();Check(!System.Text.RegularExpressions.Regex.IsMatch(html,"<script>(.*?)</script>",System.Text.RegularExpressions.RegexOptions.Singleline),"No inline boot script");var csp=string.Join(" ",root.Headers.GetValues("Content-Security-Policy"));Check(csp.Contains("script-src 'self'")&&!csp.Contains("script-src 'self' 'unsafe-inline'"),"Strict script CSP");Check(root.Headers.Contains("Strict-Transport-Security")&&root.Headers.Contains("X-Frame-Options")&&root.Headers.Contains("Permissions-Policy"),"Browser headers and HSTS");
 var anon=await c.GetAsync("/api/users");Check(anon.StatusCode==HttpStatusCode.Unauthorized,"Anonymous protected API blocked");Check(anon.Headers.CacheControl?.NoStore==true,"Protected API errors are no-store");
 var noCsrf=await Post(c,"/api/auth/login",new{email="test@example.test",password=Pass},false);Check(noCsrf.StatusCode==HttpStatusCode.BadRequest&&factory.Accounts.Attempts==0,"Missing CSRF rejected before credential verification");
 var unknown=await Post(c,"/api/auth/login",new{email="unknown@example.test",password=Pass});var wrong=await Post(c,"/api/auth/login",new{email="test@example.test",password="wrong"});Check(unknown.StatusCode==HttpStatusCode.Unauthorized&&await unknown.Content.ReadAsStringAsync()==await wrong.Content.ReadAsStringAsync(),"Unknown and wrong-password responses identical");
 var login=await Post(c,"/api/auth/login",new{email="test@example.test",password="legacy-pass-12!"});Check(login.IsSuccessStatusCode,"Existing 12-character password remains usable");Check(factory.Accounts.Upgraded is not null,"Old hash upgraded on successful login");var cookie=login.Headers.GetValues("Set-Cookie").First(x=>x.StartsWith("MPM.Auth="));Check(cookie.Contains("httponly",StringComparison.OrdinalIgnoreCase)&&cookie.Contains("secure",StringComparison.OrdinalIgnoreCase)&&cookie.Contains("samesite=strict",StringComparison.OrdinalIgnoreCase),"Actual authentication cookie flags");Check((await c.GetFromJsonAsync<JsonObject>("/api/session"))!["authenticated"]!.GetValue<bool>(),"Authenticated session");
 var weak=await Post(c,"/api/auth/password",new{currentPassword="legacy-pass-12!",password="password123456789"});Check(weak.StatusCode==HttpStatusCode.BadRequest,"Password endpoint enforces blocklist");
 using var other=Client(factory);Check((await Post(other,"/api/auth/login",new{email="test@example.test",password="legacy-pass-12!"})).IsSuccessStatusCode,"Second device login");
 var changed=await Post(c,"/api/auth/password",new{currentPassword="legacy-pass-12!",password=Pass});Check(changed.IsSuccessStatusCode,"Strong passphrase accepted");Check(!(await other.GetFromJsonAsync<JsonObject>("/api/session"))!["authenticated"]!.GetValue<bool>(),"Password change invalidates other session");
 Check((await Post(other,"/api/auth/login",new{email="test@example.test",password=Pass})).IsSuccessStatusCode,"Second device can reauthenticate");
 Check((await Post(c,"/api/auth/logout",new{})).IsSuccessStatusCode,"Logout succeeds with CSRF");Check(!(await other.GetFromJsonAsync<JsonObject>("/api/session"))!["authenticated"]!.GetValue<bool>(),"Logout revokes old session on other device");Check((await other.GetAsync("/api/users")).StatusCode==HttpStatusCode.Unauthorized,"Revoked cookie denied protected API");
 }
 using(var factory=new SecurityFactory()){factory.Accounts.Seed(Pass);using var c=Client(factory);var baseline=await Post(c,"/api/auth/login",new{email="missing@example.test",password=Pass});string expected=await baseline.Content.ReadAsStringAsync();foreach(var mode in new[]{"disabled","locked","inactive"}){var account=factory.Accounts.Account!;factory.Accounts.Account=account with{Disabled=mode=="disabled",LockedUntil=mode=="locked"?DateTime.UtcNow.AddMinutes(15):null};factory.Accounts.RoleActive=mode!="inactive";var result=await Post(c,"/api/auth/login",new{email=account.Email,password=Pass});Check(result.StatusCode==HttpStatusCode.Unauthorized&&await result.Content.ReadAsStringAsync()==expected,"Generic "+mode+" account response");}using var http=factory.CreateClient(new WebApplicationFactoryClientOptions{BaseAddress=new Uri("http://app.example.test"),AllowAutoRedirect=false});var redirect=await http.GetAsync("/");Check((int)redirect.StatusCode==307&&redirect.Headers.Location?.Scheme=="https","HTTP redirects to HTTPS");var mobile=await c.GetAsync("/mobile.html");Check(mobile.IsSuccessStatusCode&&(await mobile.Content.ReadAsStringAsync()).Contains("appearance-init.js?v=48"),"Mobile uses external CSP-compatible boot script");}
 using(var factory=new SecurityFactory()){factory.Accounts.Seed(Pass,mustChange:true);using var c=Client(factory);Check((await Post(c,"/api/auth/login",new{email="test@example.test",password=Pass})).IsSuccessStatusCode,"Temporary-password login");Check((await c.GetAsync("/api/users")).StatusCode==HttpStatusCode.Forbidden,"Mandatory password change server enforced");Check((await Post(c,"/api/auth/password",new{currentPassword=Pass,password=Pass+" changed"})).IsSuccessStatusCode,"Temporary password can be replaced");Check(!factory.Accounts.Account!.MustChange,"Mandatory-change flag cleared");}
 using(var factory=new SecurityFactory()){factory.Accounts.Seed(Pass);using var c=Client(factory);for(int n=0;n<10;n++){var r=await Post(c,"/api/auth/login",new{email="unknown@example.test",password="wrong"});Check(r.StatusCode==HttpStatusCode.Unauthorized,"Requests within login budget evaluated");}var limited=await Post(c,"/api/auth/login",new{email="unknown@example.test",password="wrong"});Check((int)limited.StatusCode==429&&limited.Headers.RetryAfter is not null,"Throttled login returns 429 and Retry-After");}
 Console.WriteLine("PASS v48 security integration: password policy/legacy hash upgrade, real cookie flags, generic login errors, CSRF, forced change, session revocation, logout, rate limiting, HTTPS headers and no-store.");
 }
}
